    T.on = false
    T.ready = {}                                   -- [layer][idx] = true once OnOpenLayer ran
    T.saved_hint = false
  end
  PlayerTraining.TrainingMode.Setup()

  -- ---- helpers ------------------------------------------------------------------------------------------------------
  function PlayerTraining.TrainingMode.Call(cmd, ...)
    local r = table.pack(pcall(funcLuaCommand, cmd, ...))
    if not r[1] then
      return nil
    end
    return table.unpack(r, 2, r.n)
  end

  function PlayerTraining.TrainingMode.Int(v)
    if type(v) ~= "number" then
      return 0
    end
    return math.floor(v + 0.5)
  end

  function PlayerTraining.TrainingMode.Signed(v)
    if v > 0 then
      return "+" .. v
    end
    return tostring(v)
  end

  -- menu_text row TX[key] (or the Spanish ES[key]) with <VALUE>/<A> = a, <B> = b
  function PlayerTraining.TrainingMode.T(key, a, b)
    local T = PlayerTraining.TrainingMode
    local s = T.Txt(T.TX[key], T.ES[key] or "")
    local map = {VALUE = a, A = a, B = b}
    return (string.gsub(s, "<(%u+)>", function(k)
      local v = map[k]
      if v == nil then
        return nil
      end
      return tostring(v)
    end))
  end

  -- visible row -> stat index (CMND_EVT_TRAIN_* / CMND_EVT_CHARA_STAT order) and back (nil for the retired 7)
  function PlayerTraining.TrainingMode.StatOf(k)
    return PlayerTraining.TrainingMode.MAP[k] or k
  end

  function PlayerTraining.TrainingMode.RowOf(i)
    for k = 0, PlayerTraining.TrainingMode.ROWS - 1 do
      if PlayerTraining.TrainingMode.MAP[k] == i then
        return k
      end
    end
    return 0
  end

  function PlayerTraining.TrainingMode.StatName(i)
    return PlayerTraining.TrainingMode.Txt(PlayerTraining.TrainingMode.TX.STATS[i + 1], PlayerTraining.TrainingMode.ES.STATS[i + 1])
  end

  function PlayerTraining.TrainingMode.Log(...)
    pcall(EVT_Call, C.EVT_LOG, "training_mode", ...)
  end

  -- the mode's layers are in the setting (training_ui_build.py deployed)
  function PlayerTraining.TrainingMode.Ready()
    local T = PlayerTraining.TrainingMode
    for _, L in ipairs({T.L_PANEL, T.L_ROW, T.L_GAUGE, T.L_CELL}) do
      local ok, e = pcall(funcLuaMenuCommand, 262659071 --[[CMND_IS_EXIST_LAYER]], L)
      if not ok or e ~= true then
        return false
      end
    end
    return true
  end

  function PlayerTraining.TrainingMode.LoaderReady()
    local T = PlayerTraining.TrainingMode
    local api, mods = T.Call(T.CMD.VERSION)
    T.pe_on = type(mods) == "number" and math.floor(mods / T.MOD_STAMINA) % 2 == 1
    return type(api) == "number" and type(mods) == "number" and math.floor(mods / T.MOD_TRAINING) % 2 == 1
  end

  -- ---- data (same reads as the v1 window) ------------------------------------------------------------------------------
  function PlayerTraining.TrainingMode.ReadInfo()
    local T = PlayerTraining.TrainingMode
    local ok, status, total, avail, level, pos, dirty, _, rule = T.Call(T.CMD.INFO, T.hdl, 0)
    -- rule 1 = pool; 0 pairs / 2 trade = counterpart rules (a raise without Libertad lowers the counterpart)
    T.info = {ok = ok == true, status = T.Int(status), total = T.Int(total), avail = T.Int(avail), level = T.Int(level),
      pos = T.Int(pos), dirty = dirty == true, pool = T.Int(rule) == 1, rule = T.Int(rule)}
  end

  -- the counterpart a raise of stat i drains next (the loader's rule: of two, the higher trained base), or nil
  function PlayerTraining.TrainingMode.Partner(i)
    local T = PlayerTraining.TrainingMode
    local s = T.st[i]
    if T.info.pool or s == nil then
      return nil
    end
    local best = nil
    for _, p in ipairs({s.p1, s.p2}) do
      local q = p ~= nil and p >= 0 and T.st[p] or nil
      if q ~= nil and (best == nil or T.Ev(q) > T.Ev(T.st[best])) then
        best = p
      end
    end
    return best
  end

  function PlayerTraining.TrainingMode.ReadStats()
    local T = PlayerTraining.TrainingMode
    T.st = {}
    for i = 0, 8 do                                -- every stat slot (7 = retired Rapidez: never shown)
      local ok, v, b, bo, d, cd, mn, mx, p1, p2 = T.Call(T.CMD.STAT, T.hdl, i)
      if ok == true then
        T.st[i] = {value = T.Int(v), base = T.Int(b), bonus = T.Int(bo), delta = T.Int(d), committed = T.Int(cd),
          min = T.Int(mn), max = T.Int(mx), p1 = T.Int(p1), p2 = T.Int(p2)}
      else
        T.st[i] = {value = 0, base = 0, bonus = 0, delta = 0, committed = 0, min = 0, max = 0, p1 = -1, p2 = -1}
      end
    end
  end

  -- the value shown and edited: the BASE stat with the working training (no equipment / beans / board)
  function PlayerTraining.TrainingMode.Ev(s)
    return s.base + s.delta
  end

  function PlayerTraining.TrainingMode.EvSaved(s)
    return s.base + s.committed
  end

  function PlayerTraining.TrainingMode.Refresh(reset_scale)
    local T = PlayerTraining.TrainingMode
    T.ReadInfo()
    if T.info.ok then
      T.ReadStats()
    end
    T.Redraw(reset_scale)
  end

  function PlayerTraining.TrainingMode.Load(fresh)
    local T = PlayerTraining.TrainingMode
    T.hdl = n
    T.hint = nil
    local ok, nm = pcall(funcLuaCommand, 1915015278 --[[CMND_GET_CHARA_NAME_TEXT]], T.hdl)
    T.name = (ok and type(nm) == "string") and nm or ""
    T.Call(T.CMD.INFO, T.hdl, fresh and 1 or 0)
    T.ReadInfo()
    T.st = {}
    if T.info.ok then
      T.ReadStats()
    end
    T.Log("player", tostring(T.hdl), "ok", tostring(T.info.ok), "status", T.info.status, "free", T.info.avail, "of",
      T.info.total, "pool", tostring(T.info.pool))
  end

  function PlayerTraining.TrainingMode.PeMax(fisico, hdl)
    local P = PlayerTraining.TrainingMode.PE
    -- the max PE is per player (IF content\match_resources\pe_max.toml): the character's handle names his card
    local ok, max = PlayerTraining.TrainingMode.Call(P.cmd, fisico, hdl or PlayerTraining.TrainingMode.pe_hdl or PlayerTraining.TrainingMode.hdl)
    if ok == true and type(max) == "number" and max > 0 then
      return math.min(P.max, math.floor(max + 0.5))
    end
    return P.fallback
  end

  -- ---- PE bar in the plate header (v3) -------------------------------------------------------------------------------
  -- Nacho 2026-09-30: «PE MÁX.» leaves the panel and becomes a thin yellow bar in the header, between the full name
  -- and the element / position / gender icons, styled like the retail bar next to «Nv.». It IS that retail bar: layer
  -- evt_trn_pebar = the header layout (soccer11_04pp, retail sprites) with every other node hidden, attached at the
  -- panel locator _atc_trnpe so the bar lands under the name; its fill is tinted yellow. Fill = PE max / 300 (the
  -- loader's [stamina] ceiling), PE max = the loader's CMND_EVT_PE_MAX (not from Físico since 2026-10-06). Only with
  -- the stamina module.
  function PlayerTraining.TrainingMode.PeBarReady()
    local ok, e = pcall(funcLuaMenuCommand, 262659071 --[[CMND_IS_EXIST_LAYER]], PlayerTraining.TrainingMode.L_PEBAR)
    return ok and e == true
  end

  function PlayerTraining.TrainingMode.PeBarClean()
    local T, P = PlayerTraining.TrainingMode, PlayerTraining.TrainingMode.PEBAR
    local L = T.L_PEBAR
    for _, pos in ipairs(P.HIDE_POS) do
      pcall(funcLuaMenuCommand, EVT_POS_VISIBLE, L, pos, false, 0)
    end
    for _, m in ipairs(P.HIDE_MESH) do
      pcall(funcLuaMenuCommand, C.MESH_VISIBLE, L, m, false, 0)
    end
    for _, t in ipairs(P.HIDE_TEXT) do
      pcall(funcLuaMenuCommand, C.TEXT, L, t, "", 0)
      pcall(funcLuaMenuCommand, 2735666188 --[[text visible]], L, t, false, 0)
    end
    for _, p in ipairs(P.HIDE_PRIM) do
      pcall(funcLuaMenuCommand, 1233047821 --[[prim visible]], L, 0, p, false)
    end
  end

  -- draw the bar for a match Físico (nil / 0 / stamina off = hidden); true when shown
  function PlayerTraining.TrainingMode.PeBar(fisico, hdl)
    local T, P = PlayerTraining.TrainingMode, PlayerTraining.TrainingMode.PEBAR
    T.pe_hdl = hdl
    local L = T.L_PEBAR
    T.pe_fisico = nil
    if not T.PeBarReady() then
      return false
    end
    if not P.ON or type(fisico) ~= "number" or fisico <= 0 or not T.pe_on then
      funcLuaMenuCommand(C.LAYER_VISIBLE, L, 0, false)
      return false
    end
    T.pe_fisico = fisico
    if not T.pe_busy then                          -- OnOpenLayer draws it again after the open: no recursion
      T.pe_busy = true
      pcall(PL.Open, L, 0)
      T.pe_busy = false
    end
    T.PeBarClean()
    if not funcLuaMenuCommand(1203687233 --[[rate bound?]], L, P.RATE, 0, 0) then
      local g = funcLuaMenuCommand(112302847 --[[CMND_GET_GROUP_INDEX]], L, 0, P.GROUP)
      funcLuaMenuCommand(541357333 --[[rate bind]], L, P.RATE, g, 0)
    end
    T.pe_value = T.PeMax(fisico, hdl)
    local r = math.max(0, math.min(1, T.pe_value / P.MAX))
    funcLuaMenuCommand(1595998683 --[[rate set]], L, P.RATE, 0, r, 0, true, P.GROUP)
    pcall(funcLuaMenuCommand, 801406373 --[[material colour]], L, 0, P.MAT, P.YELLOW[1], P.YELLOW[2], P.YELLOW[3])
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, 0, true)
    return true
  end

  -- the Supertécnicas screen itself (not the mode): the shown player's match Físico; the panel only carries the
  -- bar's locator (its own meshes are off screen, its rows / gauges / cells stay closed)
  function PlayerTraining.TrainingMode.ScreenPeBar()
    local T = PlayerTraining.TrainingMode
    if T.on or not T.PeBarReady() then
      return
    end
    if T.pe_on == nil then
      T.LoaderReady()                              -- sets pe_on (module bits of CMND_EVT_VERSION)
    end
    local f = (n ~= nil and n ~= 0) and T.Int(funcLuaCommand(C.CHARA_GET, n, 18 --[[14 + Físico]], true)) or 0
    if f > 0 and T.pe_on and T.PEBAR.ON then
      PL.Open(T.L_PANEL, 0)
      funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_PANEL, 0, true)
    end
    T.PeBar(f, n)
  end

  -- ---- screen: cover the move rows / buttons while the mode is on -------------------------------------------------------
  function PlayerTraining.TrainingMode.Cover(on)
    local T = PlayerTraining.TrainingMode
    local items = {}
    for r = 0, EVT_ROW_NUM - 1 do
      items[#items + 1] = {L_ROW, r}
    end
    items[#items + 1] = {L_CURSOR, 0}
    for _, L in ipairs({L_BTN, L_BTN_SS, PL.L_BTN_ROLE, T.L_BTN}) do
      items[#items + 1] = {L, 0}
    end
    for _, k in ipairs({EVT_ROW_ICON_SS, PL.ROW_ICON_ROLE, EVT_ROW_ICON_PV}) do   -- PV: the player-sets save icon
      items[#items + 1] = {L_PV_ROW, k}
    end
    if on then
      T.covered = {}
      for _, it in ipairs(items) do
        local ok, v = pcall(funcLuaMenuCommand, 1262717583 --[[CMND_IS_LAYER_VISIBLE]], it[1], it[2])
        T.covered[#T.covered + 1] = {it[1], it[2], not ok or v ~= false}
        funcLuaMenuCommand(C.LAYER_VISIBLE, it[1], it[2], false)
      end
    elseif T.covered ~= nil then
      for _, it in ipairs(T.covered) do
        funcLuaMenuCommand(C.LAYER_VISIBLE, it[1], it[2], it[3])
      end
      T.covered = nil
    end
  end

  -- after a player change the screen redraws its rows: hide them again (keeps the first saved visibility)
  function PlayerTraining.TrainingMode.Recover()
    local T = PlayerTraining.TrainingMode
    for _, it in ipairs(T.covered or {}) do
      funcLuaMenuCommand(C.LAYER_VISIBLE, it[1], it[2], false)
    end
  end

  function PlayerTraining.TrainingMode.OpenAll()
    local T = PlayerTraining.TrainingMode
    PL.Open(T.L_PANEL, 0)
    for _, L in ipairs({T.L_ROW, T.L_GAUGE, T.L_CELL, T.L_ARROW, T.L_KEYS}) do
      for k = 0, T.COUNT[L] - 1 do
        PL.Open(L, k)                              -- a layer missing from the setting is skipped
      end
    end
  end

  function PlayerTraining.TrainingMode.HideAll()
    local T = PlayerTraining.TrainingMode
    for L, cnt in pairs(T.COUNT) do
      for k = 0, cnt - 1 do
        pcall(funcLuaMenuCommand, C.LAYER_VISIBLE, L, k, false)   -- the optional layers may be missing
      end
    end
  end

  -- ---- drawing -------------------------------------------------------------------------------------------------------
  function PlayerTraining.TrainingMode.IsPartner(i)
    local T = PlayerTraining.TrainingMode
    if T.info.pool then
      return false
    end
    local s = T.st[T.sel]
    return s ~= nil and (s.p1 == i or s.p2 == i)
  end

  function PlayerTraining.TrainingMode.RowAlpha(i)
    local T = PlayerTraining.TrainingMode
    if T.info.pool or i == T.sel or T.IsPartner(i) then
      return 1.0
    end
    return T.DIM
  end

  -- a retail equipment plate: the stat name, the retail focus frame on the focused row (k = visible row)
  function PlayerTraining.TrainingMode.DrawRow(k)
    local T = PlayerTraining.TrainingMode
    local L = T.L_ROW
    local i = T.StatOf(k)
    for _, pos in ipairs(T.POS_LIST) do
      funcLuaMenuCommand(EVT_POS_VISIBLE, L, pos, pos == T.POS_LIST[1], k)
    end
    for _, m in ipairs(T.M_ROW_HIDE) do
      funcLuaMenuCommand(C.MESH_VISIBLE, L, m, false, k)
    end
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.M_FOCUS, i == T.sel, k)
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.ROWBAR.PLATE, T.ROWBAR.PLATE_ON, k)   -- the row's card: the name
    funcLuaMenuCommand(2575768773 --[[node pos]], L, k, T.ROWBAR.PLATE, 0, T.ROWBAR.PLATE_X)
    funcLuaMenuCommand(2885415772 --[[node scale]], L, k, T.ROWBAR.PLATE, T.ROWBAR.PLATE_W, T.ROWBAR.PLATE_H)
    funcLuaMenuCommand(2333948100 --[[text style]], L, k, T.T_ITEM, T.ST_ITEM)
    funcLuaMenuCommand(C.TEXT, L, T.T_ITEM, T.StatName(i), k)
    pcall(funcLuaMenuCommand, 4231609516 --[[model alpha]], L, k, 0, T.RowAlpha(i))
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, true)
  end

  -- bar scale: common to the 8 rows, only grows while a player is shown
  function PlayerTraining.TrainingMode.UpdateScale(reset)
    local T = PlayerTraining.TrainingMode
    local m = 0
    for i = 0, 8 do
      local s = T.st[i]
      if s then
        m = math.max(m, T.Ev(s), T.EvSaved(s))
      end
    end
    local want = math.max(100, math.ceil(m * 1.15 / 50) * 50)
    if reset or T.scale == nil or want > T.scale then
      T.scale = want
    end
  end

  function PlayerTraining.TrainingMode.SetPrim(k, prim, value, visible)
    local L = PlayerTraining.TrainingMode.L_GAUGE
    local p = funcLuaMenuCommand(1927054058 --[[CMND_SEARCH_PRIM_INDEX]], L, k, prim)
    if p ~= nil then
      funcLuaMenuCommand(3609943765 --[[prim value]], L, k, p, value, true)
    end
    funcLuaMenuCommand(1233047821 --[[prim visible]], L, k, prim, visible)
  end

  -- 2026-10-13: the dark copy of a retail stat icon (sprite crc of MENU_DEF.GetStatusParamIconName): the 7 retail
  -- icons icon_parameter01..07 of icon_common each have evt_trn_icon_parameterNN (IF content/images/menu/200_icon/
  -- 15_icon_common/training_row_icons.toml: the glyph filled with the rows' navy); unknown = the retail one
  function PlayerTraining.TrainingMode.DarkIcon(icon)
    local T = PlayerTraining.TrainingMode
    if T.darkIcons == nil then
      T.darkIcons = {}
      if type(CALC_CRC) == "function" then
        for n = 1, 7 do
          local name = string.format("icon_parameter%02d", n)
          T.darkIcons[CALC_CRC(name)] = CALC_CRC(T.DARK_ICON_PREFIX .. name)
        end
      end
    end
    return T.darkIcons[icon] or icon
  end

  -- the column backing (spare gauge instance ROWS): only the pill shows, stretched over rows 1..8
  function PlayerTraining.TrainingMode.DrawBack()
    local T = PlayerTraining.TrainingMode
    local L, k, B = T.L_GAUGE, T.ROWS, T.ROWBAR
    if not (T.ready[L] or {})[k] then
      return
    end
    local gp = 499270986 --[[CMND_GET_MESH_GLOBAL_POSITION]]
    local ok0, _, y0 = pcall(funcLuaMenuCommand, gp, L, 0, T.KEYS.BASE)
    local ok1, _, y1 = pcall(funcLuaMenuCommand, gp, L, k, T.KEYS.BASE)
    if not (T.info.ok and ok0 and ok1 and type(y0) == "number" and type(y1) == "number" and y0 ~= y1) then
      funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, false)
      return
    end
    local gk = B.GAUGE_K
    local pitch = math.abs(y0 - y1) / k / gk                     -- gauge units between two rows
    local h = B.PLATE_H / gk
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.M_ICON, false, k)
    funcLuaMenuCommand(C.MESH_VISIBLE, L, B.SLASH, false, k)
    for _, p in ipairs({T.P_NUM_CUR, T.P_NUM_NEXT, T.P_NUM_MAX}) do
      T.SetPrim(k, p, 0, false)
    end
    funcLuaMenuCommand(2575768773 --[[node pos]], L, k, B.NODE, 0, -5000)   -- the bar parked off screen
    funcLuaMenuCommand(C.MESH_VISIBLE, L, B.PILL, true, k)
    funcLuaMenuCommand(2575768773, L, k, B.PILL, 0, (B.BACK.X0 - B.GAUGE_X0) / gk)
    funcLuaMenuCommand(2575768773, L, k, B.PILL, 1, k * pitch + h / 2)
    funcLuaMenuCommand(2885415772 --[[node scale]], L, k, B.PILL, (B.BACK.X1 - B.BACK.X0) / gk, (k - 1) * pitch + h)
    pcall(funcLuaMenuCommand, 4231609516 --[[model alpha]], L, k, 0, 1.0)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, true)
  end

  -- the retail stat gauge: icon, "value / max" (green «next» number when raised), bar (red part = the lowered value)
  function PlayerTraining.TrainingMode.DrawGauge(k)
    local T = PlayerTraining.TrainingMode
    if k == T.ROWS then
      return T.DrawBack()
    end
    local i = T.StatOf(k)
    local s = T.st[i]
    if not (T.ready[T.L_GAUGE] or {})[k] then
      return
    end
    if s == nil or not T.info.ok then
      funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_GAUGE, k, false)
      return
    end
    local v, old, top = T.Ev(s), T.EvSaved(s), s.base + s.max
    T.SetPrim(k, T.P_NUM_CUR, math.max(0, v), v <= old)
    T.SetPrim(k, T.P_NUM_NEXT, math.max(0, v), v > old)
    T.SetPrim(k, T.P_NUM_MAX, math.max(0, top), true)
    local r = math.max(0, math.min(1, v / T.scale))
    local r_old = math.max(0, math.min(1, old / T.scale))
    funcLuaMenuCommand(1595998683 --[[rate set]], T.L_GAUGE, T.R_GAUGE, 0, r, k, false, T.G_BAR)
    funcLuaMenuCommand(1595998683 --[[rate set]], T.L_GAUGE, T.R_GAUGE_RED, 0, math.max(r, r_old), k, false, T.G_BAR)
    pcall(funcLuaMenuCommand, 4231609516 --[[model alpha]], T.L_GAUGE, k, 0, T.RowAlpha(i))
    local B = T.ROWBAR
    funcLuaMenuCommand(C.MESH_VISIBLE, T.L_GAUGE, B.PILL, B.PILL_ON, k)   -- no navy capsule per row
    funcLuaMenuCommand(2575768773 --[[node pos]], T.L_GAUGE, k, B.NODE, 0, B.X)
    funcLuaMenuCommand(2575768773, T.L_GAUGE, k, B.NODE, 1, B.Y)
    funcLuaMenuCommand(2885415772 --[[node scale]], T.L_GAUGE, k, B.NODE, B.SX, B.SY)
    for _, m in ipairs(B.MOVE) do                  -- icon left of the name, the numbers above the bar
      funcLuaMenuCommand(2575768773, T.L_GAUGE, k, m[1], 0, m[2])
      funcLuaMenuCommand(2575768773, T.L_GAUGE, k, m[1], 1, m[3])
    end
    funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_GAUGE, k, true)
    if i == T.sel then
      pcall(T.DrawKeys, k)
    end
  end

  -- the focused row's -1 / +1 key glyphs (layer evt_trn_keys), placed from the gauge's origin node (DrawGauge moves
  -- the icon / number nodes in the same frame: their global position would still be the old one)
  function PlayerTraining.TrainingMode.DrawKeys(k)
    local T, K = PlayerTraining.TrainingMode, PlayerTraining.TrainingMode.KEYS
    local L = T.L_KEYS
    if funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER]], L) ~= true then
      return
    end
    local gp = 499270986 --[[CMND_GET_MESH_GLOBAL_POSITION]]
    local ok1, ix, iy = pcall(funcLuaMenuCommand, gp, T.L_GAUGE, k, K.BASE)
    if not (ok1 and type(ix) == "number" and type(iy) == "number") then
      return
    end
    local at = {[0] = {ix + K.L_DX, iy + K.DY, T.I_LEFT}, {ix + K.R_DX, iy + K.DY, T.I_RIGHT}}
    for j = 0, 1 do
      if (T.ready[L] or {})[j] then
        local okg, glyph = pcall(funcLuaCommand, 4074371074 --[[CMND_TEXT_GET]], at[j][3])
        funcLuaMenuCommand(1083631230 --[[CMND_SET_MENU_TEXT_STRING]], L, K.TEXT,
          okg and type(glyph) == "string" and glyph or "", j)
        funcLuaMenuCommand(1595998683 --[[rate]], L, K.RATE, 0, 0, j)
        funcLuaMenuCommand(3778714801 --[[CMND_SET_LAYER_LOCAL_SCALE]], L, K.SCALE, K.SCALE, 1, j)
        funcLuaMenuCommand(1389957207 --[[CMND_SET_LAYER_LOCAL_POS]], L, at[j][1], at[j][2], 0, j)
        funcLuaMenuCommand(C.LAYER_VISIBLE, L, j, T.info.ok == true)
      end
    end
    if not K.logged then
      K.logged = true
      T.Log("keys", "row", k, "gauge origin", ix, iy)
    end
  end

  -- ---- trade arrows (v4) ---------------------------------------------------------------------------------------------
  -- UP on the focused stat's row, DOWN on the row of the counterpart a raise drains (T.Partner: none with the pool
  -- rule or without a counterpart). Drawn like the retail UpdateCharaParameterGraphNextBeansByCharaStHdl draws its
  -- radar numbers: both side groups hidden, the chosen stack shown, the chevrons swapped to arrow_u02 / arrow_d02.
  function PlayerTraining.TrainingMode.ArrowReady()
    local ok, e = pcall(funcLuaMenuCommand, 262659071 --[[CMND_IS_EXIST_LAYER]], PlayerTraining.TrainingMode.L_ARROW)
    return ok and e == true
  end

  -- [instance] = true for the arrows to show now
  function PlayerTraining.TrainingMode.ArrowWant()
    local T = PlayerTraining.TrainingMode
    local want = {}
    if not T.on or T.info == nil or not T.info.ok or T.st == nil or T.st[T.sel] == nil then
      return want
    end
    want[T.RowOf(T.sel)] = true
    local p = T.Partner(T.sel)
    if p ~= nil and T.MAP[T.RowOf(p)] == p then  -- a shown stat (never the retired slot 7)
      want[T.ARROW.ROWS + T.RowOf(p)] = true
    end
    return want
  end

  function PlayerTraining.TrainingMode.DrawArrow(i, want)
    local T, A = PlayerTraining.TrainingMode, PlayerTraining.TrainingMode.ARROW
    local L = T.L_ARROW
    if not (T.ready[L] or {})[i] then
      return
    end
    if not (want or T.ArrowWant())[i] then
      funcLuaMenuCommand(C.LAYER_VISIBLE, L, i, false)
      return
    end
    local up = i < A.ROWS
    pcall(funcLuaMenuCommand, 551395392 --[[number prims visible]], L, i, false)
    for _, p in ipairs(A.PRIMS) do
      pcall(funcLuaMenuCommand, 1233047821 --[[prim visible]], L, i, p, false)
    end
    funcLuaMenuCommand(EVT_POS_VISIBLE, L, A.NUM, false, i)
    for _, s in ipairs(A.SIDES) do
      funcLuaMenuCommand(EVT_POS_VISIBLE, L, s, false, i)
    end
    funcLuaMenuCommand(EVT_POS_VISIBLE, L, up and A.UP or A.DOWN, true, i)
    local spr = up and A.SPR_UP or A.SPR_DOWN
    funcLuaMenuCommand(C.SPRITE, L, A.TEX, spr[1], spr[2], 0, i)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, i, true)
  end

  function PlayerTraining.TrainingMode.DrawArrows()
    local T = PlayerTraining.TrainingMode
    if not T.ArrowReady() then
      return
    end
    local want = T.ArrowWant()
    for i = 0, T.COUNT[T.L_ARROW] - 1 do
      T.DrawArrow(i, want)
    end
  end

  function PlayerTraining.TrainingMode.Cell(L, k, label, value)
    funcLuaMenuCommand(C.TEXT, L, PlayerTraining.TrainingMode.T_LABEL, label, k)
    funcLuaMenuCommand(C.TEXT, L, PlayerTraining.TrainingMode.T_VALUE, value, k)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, true)
  end

  -- right: the screen's detail panel (band = the focused stat, its icon big) + 2 cells in its text area
  function PlayerTraining.TrainingMode.DrawPanel()
    local T = PlayerTraining.TrainingMode
    local i = T.sel
    local icon = i < 7 and MENU_DEF.GetStatusParamIconName(i) or 0
    pcall(PL.PanelPlain, 5, T.StatName(i), "", icon ~= 0 and function(L)
      funcLuaMenuCommand(C.SPRITE, L, T.ICON_TEX, icon, PL.SLOT_AREA, 0, 0)
    end or nil)
    PL.hiper_wide = false
    -- the focused stat's name on the purple bar (PanelPlain leaves it hidden); the retail position tag stays hidden
    funcLuaMenuCommand(2735666188 --[[text visible]], L_DETAIL, 1704438437 --[[_text_name01]], true, 0)
    PL.TypeTagOff()
    pcall(EVT_DetailGraphSync)
    local s = T.st[i]
    if not T.info.ok or s == nil then
      for k = 0, T.COUNT[T.L_CELL] - 1 do
        funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_CELL, k, false)
      end
      return
    end
    -- v4 (Nacho 2026-09-30: «quita contraria, subido y bajado, deja solo la libertad y el valor base»): two cells,
    -- centred in the panel's text area (training_ui_build.py CELLS): LIBERTAD = the player's free points LEFT (it goes
    -- down as they are spent) · VALOR BASE = the focused stat's untrained base (the floor for lowering by hand). What
    -- a raise costs is shown by the arrows of the stat list and the guide line.
    T.Cell(T.L_CELL, 0, T.T("C_LIB"), tostring(math.max(0, T.info.avail)))
    T.Cell(T.L_CELL, 1, T.T("C_VALUE"), tostring(s.base))
    T.HookDetailLayout()
    pcall(PL.SetDetailLayout, "training")         -- 2026-10-07: the stat banner / cells inside the one white card
  end

  -- The training view's card, laid out from one rect (screen px of the 1920 x 1080 menu space, y down). A text node
  -- does not move by node translation, so the stat name stays at its layout x (NAME_X from the detail locator): the
  -- locator itself is placed so the name lands right of the icon, and the band / icon meshes are placed back from it.
  PlayerTraining.TrainingMode.DETAIL = {
    CARD = {985, 640, 1920, 852},                  -- x0, y0, x1, y1: flush to the screen's right edge, as the player page's cards
    PAD = 12,                                      -- card left edge -> icon
    ICON = 64,                                     -- icon size
    GAP = 10,                                      -- icon -> name
    NAME_X = -261,                                 -- _text_name01 x in evt_team02_02_detail (from the locator)
    BAND_Y = 188, BAND_H = 88, ICON_Y = 176,       -- layout units from the locator, y up
    BAND_INSET = 0,                                -- band right end inside the card
    LOCATOR = 1,                                   -- PL.LAYOUT_LOCS index of _pos_evt_detail01
    BAND_NODES = {1125548721 --[[_sp_base01]], 3384915402 --[[_wlv_base01]]},
    ICON_NODE = 2164615260,                        -- _icon_sp_area_dmy01
    HIDE_MESH = {656425078 --[[_item_win_line01]], 3303013605 --[[_sp_win_base01]]},
    FLAVOR = 691026122,                            -- _text_flavor01
  }

  -- after the screen's own ApplyDetailLayout: while the training view is shown, its card geometry (above)
  function PlayerTraining.TrainingMode.ApplyCard()
    local T, D = PlayerTraining.TrainingMode, PlayerTraining.TrainingMode.DETAIL
    if not T.on or PL.layout_mode ~= "training" then
      return
    end
    local x0, x1 = D.CARD[1], D.CARD[3]
    local loc = PL.LAYOUT_LOCS[D.LOCATOR]
    local _, ly = PL.LayoutLoc(D.LOCATOR)
    local lx = x0 + D.PAD + D.ICON + D.GAP - D.NAME_X
    if loc ~= nil and funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER]], L_BASE) then
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_BASE, 0, loc[1], 0, lx)
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_BASE, 0, loc[1], 1, ly)
    end
    if funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER]], L_DETAIL) then
      for _, node in ipairs(D.BAND_NODES) do
        funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, node, 0, x0 - lx)
        funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, node, 1, D.BAND_Y)
        funcLuaMenuCommand(2885415772 --[[node scale]], L_DETAIL, 0, node, x1 - x0 - D.BAND_INSET, D.BAND_H)
      end
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, D.ICON_NODE, 0, x0 + D.PAD - lx)
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, D.ICON_NODE, 1, D.ICON_Y)
      funcLuaMenuCommand(2885415772 --[[node scale]], L_DETAIL, 0, D.ICON_NODE, D.ICON, D.ICON)
      for _, mesh in ipairs(D.HIDE_MESH) do         -- the description's divider line and window: no description here
        funcLuaMenuCommand(C.MESH_VISIBLE, L_DETAIL, mesh, false, 0)
      end
      funcLuaMenuCommand(2735666188 --[[text visible]], L_DETAIL, D.FLAVOR, false, 0)
    end
    if type(EVT_PPG_HOST) == "table" then
      EVT_PPG_HOST.card = D.CARD
    end
  end

  -- wraps the screen's PL.ApplyDetailLayout once per VM (it runs on every state change and for a few frames after)
  function PlayerTraining.TrainingMode.HookDetailLayout()
    local base = PL.ApplyDetailLayout
    if type(base) ~= "function" or PL.training_card_wrap == base then
      return
    end
    local wrapped = function(...)
      base(...)
      pcall(PlayerTraining.TrainingMode.ApplyCard)
    end
    PL.training_card_wrap = wrapped
    PL.ApplyDetailLayout = wrapped
  end

  -- the screen's radar: BASE stats (base + saved training) + the pending change as the retail arrows. The retail
  -- function draws "stat without beans" + a4 (+ a5 - a4 as the arrow): a4 / a5 are offsets from that value.
  function PlayerTraining.TrainingMode.DrawGraph()
    local T = PlayerTraining.TrainingMode
    if not T.info.ok or UpdateCharaParameterGraphNextBeansByCharaStHdl == nil then
      return
    end
    local a4, a5 = {}, {}
    for t = 0, 7 do
      local s = T.st[t] or {base = 0, delta = 0, committed = 0}
      if t < 7 then
        local nob = T.Int(funcLuaCommand(C.CHARA_GET, T.hdl, 14 + t, true, true))
        a4[t + 1] = T.EvSaved(s) - nob
        a5[t + 1] = T.Ev(s) - nob
      else
        a4[t + 1] = 0
        a5[t + 1] = 0
      end
    end
    local ok, err = pcall(UpdateCharaParameterGraphNextBeansByCharaStHdl, T.GRAPH[1], T.GRAPH[2], T.hdl, a4, a5,
      T.GRAPH[3])
    if not ok then
      T.Log("graph", tostring(err))
    end
  end

  function PlayerTraining.TrainingMode.DrawGuide()
    local T = PlayerTraining.TrainingMode
    local line = T.hint
    if line == nil then
      if not T.info.ok then
        line = T.info.status == T.ERR_LOCKED and T.T("LOCKED") or T.T("NO_DATA")
      else
        -- 2026-10-15 (owner): only this line (the keys are on the focused row; the Libertad is in the panel)
        line = T.T("GUIDE_SHORT")
      end
    end
    PL.Guide(line)
    local keys = {}
    if T.info.ok then
      keys = {{text = T.TX.G_ACCEPT, icon = PL.I_ENTER, cmd = PL.K_ENTER},
        {text = T.TX.G_SAVE, icon = PL.I_FUNC4, cmd = PL.K_FUNC4},
        {text = T.TX.G_RESET, icon = PL.I_FUNC1, cmd = PL.K_FUNC1}}
      -- 2026-10-07: no «-1» / «+1» entries (the focused row shows its two keys, PlayerTraining.TrainingMode.DrawKeys)
    end
    -- 2026-10-07 (Nacho): no «C Jugador» entry (the Z / C arrows by the portrait tell it; the key still works)
    keys[#keys + 1] = {text = T.TX.G_BACK, icon = PL.I_BACK, cmd = PL.K_BACK}
    pcall(PL.GuideKeys, keys)
  end

  function PlayerTraining.TrainingMode.Redraw(reset_scale)
    local T = PlayerTraining.TrainingMode
    T.UpdateScale(reset_scale)
    PL.Open(T.L_PANEL, 0)
    funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_PANEL, 0, true)
    for k = 0, T.ROWS - 1 do
      T.DrawRow(k)
      T.DrawGauge(k)
    end
    for k = T.ROWS, T.COUNT[T.L_ROW] - 1 do          -- the layout's 9th row / gauge (ex Rapidez): hidden
      funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_ROW, k, false)
      funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_GAUGE, k, false)
    end
    T.DrawBack()                                     -- the column backing: gauge instance ROWS
    T.DrawArrows()
    T.DrawPanel()
    T.DrawGraph()
    T.DrawGuide()
    local f = T.info.ok and T.st[4] or nil          -- Físico: the match value with the working change
    pcall(T.PeBar, f ~= nil and f.value or nil)
  end

  -- ---- actions -------------------------------------------------------------------------------------------------------
  function PlayerTraining.TrainingMode.Commit()
    local T = PlayerTraining.TrainingMode
    if not T.info.ok or not T.info.dirty then
      return true
    end
    local ok, status = T.Call(T.CMD.COMMIT, T.hdl)
    T.Log("commit", tostring(T.hdl), tostring(ok), tostring(status))
    if ok ~= true then
      EVT_Message(T.T("SAVE_FAILED", T.Int(status)))
      return false
    end
    return true
  end

  -- Aceptar (close = true) / Guardar (close = false); false = the save failed
  function PlayerTraining.TrainingMode.Save(close)
    local T = PlayerTraining.TrainingMode
    local dirty = T.info.ok and T.info.dirty
    if not T.Commit() then
      return false
    end
    funcLuaCommand(C.SE, SE_DECIDE)
    if dirty and not T.saved_hint then
      T.saved_hint = true
      EVT_Message(T.T("SAVED"))
    end
    if not close then
      T.hint = nil
      T.Refresh(false)
      pcall(UpdateCharaStatus)
    end
    return true
  end

  -- Atrás: true = leave the mode (asks when there are unsaved changes)
  function PlayerTraining.TrainingMode.Back()
    local T = PlayerTraining.TrainingMode
    if T.info.ok and T.info.dirty then
      funcLuaCommand(C.SE, SE_OK)
      if not PL.MxAsk(T.T("ASK_DISCARD")) then
        T.DrawGuide()
        return false
      end
    end
    funcLuaCommand(C.SE, SE_BACK)
    return true
  end

  function PlayerTraining.TrainingMode.Reset()
    local T = PlayerTraining.TrainingMode
    if not T.info.ok then
      funcLuaCommand(C.SE, SE_NG)
      return
    end
    if PL.MxAsk(T.T("ASK_RESET", T.name)) then
      T.Call(T.CMD.RESET, T.hdl)
      funcLuaCommand(C.SE, SE_OK)
    end
    T.hint = nil
    T.Refresh(false)
  end

  function PlayerTraining.TrainingMode.Row(dir)
    local T = PlayerTraining.TrainingMode
    T.hint = nil
    T.sel = T.StatOf((T.RowOf(T.sel) + dir) % T.ROWS)
    funcLuaCommand(C.SE, 2500047763 --[[sy0005 cursor]])
    T.Redraw(false)
  end

  function PlayerTraining.TrainingMode.Step(dir)
    local T = PlayerTraining.TrainingMode
    if not T.info.ok then
      funcLuaCommand(C.SE, SE_NG)
      return
    end
    if dir == T.lastDir and T.frame - T.lastFrame <= T.HOLD_GAP then
      T.rep = T.rep + 1
    else
      T.rep = 0
    end
    T.lastDir, T.lastFrame = dir, T.frame
    local amount = (T.step10 or T.rep >= T.HOLD_REPEATS) and 10 or 1
    local s = T.st[T.sel]
    local ok, stop, reached = T.Call(T.CMD.SET, T.hdl, T.sel, s.delta + dir * amount)
    if type(reached) ~= "number" or T.Int(reached) == s.delta then
      funcLuaCommand(C.SE, SE_NG)
    else
      funcLuaCommand(C.SE, 2500047763 --[[sy0005 cursor]])
    end
    -- why it stopped (also after a partial 10-point step) -> the guide line: pool empty / no Libertad and the
    -- counterpart at its floor / by hand at the base (trade) or at the floor (pool) / cap
    T.hint = nil
    stop = T.Int(stop)
    if ok ~= true and stop == 1 and T.info.pool then
      T.hint = T.T("EMPTY")
    elseif ok ~= true and stop == 1 then
      local pair = T.Partner(T.sel)
      T.hint = T.T("NO_TRADE", T.StatName(T.sel), pair ~= nil and T.StatName(pair) or "-")
    elseif ok ~= true and (stop == 3 or (stop == 5 and not T.info.pool)) then
      T.hint = T.T("FLOOR_BASE", T.StatName(T.sel), s.base)
    elseif ok ~= true and stop == 5 then
      T.hint = T.T("FLOOR", T.StatName(T.sel), s.base + s.min)
    elseif ok ~= true and stop == 2 then
      T.hint = T.T("CAP", T.StatName(T.sel), s.base + s.max)
    end
    T.Refresh(false)
  end

  -- L1 / R1: previous / next player of the screen (its own switch: sort order n5 over n15 members, ChangeChara)
  function PlayerTraining.TrainingMode.Switch(dir)
    local T = PlayerTraining.TrainingMode
    if n15 == nil or n15 <= 1 then
      funcLuaCommand(C.SE, SE_NG)
      return
    end
    if T.info.ok and T.info.dirty then
      if PL.MxAsk(T.T("ASK_SWITCH", T.name)) then
        if not T.Commit() then
          T.DrawGuide()
          return
        end
      else
        T.Call(T.CMD.CANCEL, T.hdl)
      end
    end
    funcLuaCommand(C.SE, 3791946501 --[[sy0004]])
    funcLuaMenuCommand(3781155141 --[[CMND_PLAY_ANIME_TYPE]], L_BASE, 0, dir < 0 and 1203080170 or 3183130249, 0,
      3627544126)
    for _ = 1, n15 do
      n5 = (n5 + dir) % n15
      n4 = GetCharaIndexBySortIndex(n5)
      if t4[n4 + 1] ~= 0 then
        break
      end
    end
    local ok, err = pcall(ChangeChara, n4)
    if not ok then
      T.Log("ChangeChara", tostring(err))
    end
    T.Recover()
    T.Load(true)
    T.Redraw(true)
  end

  -- ---- the mode (runs as evt_co, resumed by the screen's Step) -----------------------------------------------------------
  function PlayerTraining.TrainingMode.Mode()
    local T = PlayerTraining.TrainingMode
    funcLuaMenuCommand(C.MENU_ACTIVE, T.EVT_MENU, false)
    if not T.LoaderReady() then
      funcLuaCommand(C.SE, SE_NG)
      EVT_Message(T.T("NO_LOADER"))
      funcLuaMenuCommand(C.MENU_ACTIVE, T.EVT_MENU, true)
      return
    end
    funcLuaCommand(C.SE, SE_DECIDE)
    T.on = true
    T.sel, T.step10, T.hint = 0, false, nil
    T.frame, T.lastDir, T.lastFrame, T.rep = 0, 0, -100, 0
    T.scale = nil
    pcall(EVT_DetailHide)
    T.Cover(true)
    T.OpenAll()
    T.Load(true)
    T.Log("mode on", tostring(T.hdl))
    local wait = 0                                 -- the gauges bind their bars in OnOpenLayer
    while wait < 30 do
      local all = true
      for k = 0, T.ROWS - 1 do
        all = all and (T.ready[T.L_GAUGE] or {})[k] == true
      end
      if all then
        break
      end
      wait = wait + 1
      coroutine.yield()
    end
    T.Redraw(true)
    coroutine.yield()                              -- the Aceptar that opened the mode must not count
    while true do
      coroutine.yield()
      T.frame = T.frame + 1
      if PL.Key(EVT_CMD_BACK) then
        if T.Back() then
          break
        end
      elseif T.info.ok and (PL.Key(PL.K_ENTER) or PL.Key(T.K_CLICK)) then
        if T.Save(true) then
          break
        end
      elseif T.info.ok and PL.Key(PL.K_FUNC4) then
        T.Save(false)
      elseif PL.Key(PL.K_FUNC1) then
        T.Reset()
      elseif PL.Key(EVT_CMD_UP) then
        T.Row(-1)
      elseif PL.Key(EVT_CMD_DOWN) then
        T.Row(1)
      elseif PL.Key(T.K_LEFT) then
        T.Step(-1)
      elseif PL.Key(T.K_RIGHT) then
        T.Step(1)
      elseif PL.Key(T.K_L1) then
        T.Switch(-1)
      elseif PL.Key(T.K_R1) then
        T.Switch(1)
      elseif PL.Key(T.K_FUNC2) then
        T.hint = nil
        T.step10 = not T.step10
        funcLuaCommand(C.SE, SE_OK)
        T.DrawGuide()
      end
    end
    T.Exit()
  end

  function PlayerTraining.TrainingMode.Exit()
    local T = PlayerTraining.TrainingMode
    T.Call(T.CMD.CANCEL, 0)                        -- drop every working copy (saved training stays)
    T.on = false
    T.HideAll()
    pcall(PL.DetailHideAll)
    T.Cover(false)
    coroutine.yield()                              -- the closing input must not reach the screen
    pcall(EVT_RefreshRows)
    pcall(UpdateCharaStatus)                       -- player card (shown stats include the training)
    pcall(UpdateEquipItemInfo)                     -- radar, detail panel, button guide of the screen
    pcall(T.Label)
    pcall(T.Guide)
    funcLuaMenuCommand(C.MENU_ACTIVE, T.EVT_MENU, true)
    T.Log("mode off", tostring(n))
  end

  -- Aceptar on «Entrenar»: the mode, or the v1 window when the mode's layers are not in the setting
  function PlayerTraining.TrainingMode.Coroutine()
    if PlayerTraining.TrainingMode.Ready() then
      return PlayerTraining.TrainingMode.Mode()
    end
    return PlayerTraining.TrainingMode.WindowCoroutine()
  end

  -- ================================================================================================================
  -- on Character Reforged's skill table host
  -- ================================================================================================================
  -- the footer button (content\menus\skill_table_training.toml): "guide" -> the guide line, "press" -> the mode (or
  -- the v1 window), run as the screen's action coroutine
  function PlayerTraining.SkillTableButton(phase, ctx)
    local T = PlayerTraining.TrainingMode
    if phase == "guide" then
      return T.Txt(T.TX_GUIDE, "Reparte los puntos de Libertad entre las estadísticas base de este jugador.")
    elseif phase == "press" then
      T.Log("button pressed", tostring(ctx and ctx.chara))
      return T.Coroutine()
    end
    return nil
  end

  -- a callback of the screen: a VRFW_Host «around» handler of the host evt_skill_slot_menu, or (no host) a wrapper of
  -- the global; handler(next_handler, ...) calls next_handler(...) for everything that is not the mode's
  function PlayerTraining.TrainingMode.Hook(point, handler)
    local T = PlayerTraining.TrainingMode
    if SkillTable.hosted and type(VRFW_Host) == "table" and type(VRFW_Host.on) == "function" then
      VRFW_Host.on("evt_skill_slot_menu", point, {id = "player_training.training_mode", phase = "around", fn = handler})
      return
    end
    T.wrapped = T.wrapped or {}
    local previous = _ENV[point]
    if T.wrapped[point] or type(previous) ~= "function" then
      return
    end
    T.wrapped[point] = true
    _ENV[point] = function(...)
      return handler(previous, ...)
    end
  end

  -- the mode's layers: hidden until the mode draws them
  PlayerTraining.TrainingMode.Hook("OnSetupLayer", function(next_handler, a1, a2, ...)
    local T = PlayerTraining.TrainingMode
    if T.COUNT[a1] ~= nil then
      local prio = T.PRIO[a1]
      if a1 == T.L_GAUGE and a2 == T.ROWS then
        prio = T.ROWBAR.BACK.PRIO                  -- the column backing: under everything else
      end
      funcLuaMenuCommand(EVT_PRIORITY, a1, a2, prio, true)
      funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, false)
      return
    end
    return next_handler(a1, a2, ...)
  end)

  PlayerTraining.TrainingMode.Hook("OnOpenLayer", function(next_handler, a1, a2, ...)
    local T = PlayerTraining.TrainingMode
    if T.COUNT[a1] ~= nil then
      if a1 == T.L_GAUGE and a2 == T.ROWS then     -- the column backing: its sprite
        funcLuaMenuCommand(C.SPRITE, a1, T.ROWBAR.BACK_TEX, T.ROWBAR.BACK.SPRITE, T.ROWBAR.BACK_SLOT, 0, a2)
      end
      if a1 == T.L_GAUGE and a2 ~= nil and a2 >= 0 and a2 < T.ROWS then
        local icon = a2 < 7 and MENU_DEF.GetStatusParamIconName(a2) or 0
        if icon ~= 0 then
          funcLuaMenuCommand(C.SPRITE, a1, T.ICON_TEX, T.DarkIcon(icon), T.ICON_NODE, 0, a2)
        else
          funcLuaMenuCommand(C.MESH_VISIBLE, a1, T.M_ICON, false, a2)   -- row 7 = Suerte: no retail icon
        end
        local g = funcLuaMenuCommand(112302847 --[[CMND_GET_GROUP_INDEX]], a1, a2, T.G_BAR)
        funcLuaMenuCommand(541357333 --[[rate bind]], a1, T.R_GAUGE, g, a2)
        funcLuaMenuCommand(541357333 --[[rate bind]], a1, T.R_GAUGE_RED, g, a2)
      end
      T.ready[a1] = T.ready[a1] or {}
      T.ready[a1][a2 or 0] = true
      if a1 == T.L_PEBAR then                      -- the open resets the layout: hide the header parts again
        pcall(T.PeBarClean)
        if T.pe_fisico ~= nil then
          if not T.pe_busy then
            pcall(T.PeBar, T.pe_fisico)
          end
        else
          funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, false)
        end
      elseif a1 == T.L_PANEL and not T.on and T.pe_fisico ~= nil then
        funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, true)   -- the screen's PE bar hangs on it
      elseif not T.on then
        funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, false)
      elseif a1 == T.L_GAUGE then
        pcall(T.DrawGauge, a2)
      elseif a1 == T.L_ROW then
        pcall(T.DrawRow, a2)
      elseif a1 == T.L_ARROW then
        pcall(T.DrawArrow, a2)
      end
      return
    end
    return next_handler(a1, a2, ...)
  end)

  -- v3: the plate header's PE bar follows the shown player (the screen redraws its header here)
  PlayerTraining.TrainingMode.Hook("UpdateCharaStatus", function(next_handler, ...)
    local r = table.pack(next_handler(...))
    pcall(PlayerTraining.TrainingMode.ScreenPeBar)
    return table.unpack(r, 1, r.n)
  end)
  end
end
